import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../../api.js';

function newScope(mapId) {
  return { mapId, undo: [], redo: [], queue: Promise.resolve(), generation: 0, mounted: true, pending: 0 };
}

function canceledOperation() {
  return Object.assign(new Error('地图已切换或内容已更新，本次操作已取消。'), { name: 'AbortError' });
}

// Snapshots are generated by the server; fingerprints protect both sides of
// each edit and every restore against intervening collaboration changes.
export default function useEditorHistory({ mapId, canEdit, onApply, onError }) {
  const [undoEntries, setUndoEntries] = useState([]);
  const [redoEntries, setRedoEntries] = useState([]);
  const [busy, setBusy] = useState(false);
  const refs = useRef(newScope(mapId));
  // A pending request belongs to the map on which it started, including between
  // the new map's render and its effect. Do not let it use the new callbacks.
  if (refs.current.mapId !== mapId) {
    refs.current.mounted = false;
    refs.current.generation += 1;
    refs.current = newScope(mapId);
  }
  const optionsRef = useRef({ canEdit, onApply, onError });
  optionsRef.current = { canEdit, onApply, onError };
  const activeScope = refs.current;
  const sync = useCallback(() => {
    if (!refs.current.mounted) return;
    setUndoEntries([...refs.current.undo]);
    setRedoEntries([...refs.current.redo]);
  }, []);
  const clear = useCallback(() => {
    if (refs.current !== activeScope || !activeScope.mounted) return;
    activeScope.generation += 1;
    activeScope.undo = [];
    activeScope.redo = [];
    sync();
  }, [activeScope, sync]);
  useEffect(() => {
    const scope = refs.current;
    scope.mounted = true;
    clear();
    setBusy(scope.pending > 0);
    return () => { scope.mounted = false; scope.generation += 1; };
  }, [mapId, clear]);
  const enqueue = useCallback((operation, operationMapId) => {
    const scope = refs.current;
    if (!scope.mounted || scope.mapId !== operationMapId) return Promise.reject(canceledOperation());
    const generation = scope.generation;
    const isCurrent = () => refs.current === scope && scope.mounted && scope.generation === generation;
    const assertCurrent = () => { if (!isCurrent()) throw canceledOperation(); };
    scope.pending += 1;
    setBusy(true);
    const result = scope.queue.catch(() => {}).then(() => {
      assertCurrent();
      return operation({ scope, isCurrent, assertCurrent });
    }).catch((error) => {
      // The operation may deliberately clear this map's generation on a 409.
      // Preserve that error, while suppressing errors from a departed map.
      if (refs.current !== scope || !scope.mounted) throw canceledOperation();
      throw error;
    });
    scope.queue = result;
    return result.finally(() => {
      scope.pending -= 1;
      if (refs.current === scope && scope.mounted) setBusy(scope.pending > 0);
    });
  }, []);
  const run = useCallback((label, mutation, { record = true } = {}) => enqueue(async ({ scope, isCurrent, assertCurrent }) => {
    if (!optionsRef.current.canEdit) throw new Error('当前为只读权限');
    let before;
    try { before = await api.createCheckpoint(mapId); }
    catch (error) { assertCurrent(); throw error; }
    assertCurrent();
    if (!optionsRef.current.canEdit) throw new Error('当前为只读权限');
    let data;
    try {
      data = await mutation(before.fingerprint);
      assertCurrent();
      if (data?.layers) optionsRef.current.onApply?.(data);
    } catch (error) {
      if (!isCurrent()) throw canceledOperation();
      if (error.conflict || error.status === 409) clear();
      throw error;
    }
    if (!record) {
      // A committed local media edit ends the old history, but later user
      // edits already in this queue still belong to the same valid session.
      scope.undo = [];
      scope.redo = [];
      sync();
      return data;
    }
    if (!data?.contentFingerprint) { clear(); return data; }
    try {
      const after = await api.createCheckpoint(mapId, { expectedFingerprint: data.contentFingerprint });
      assertCurrent();
      if (before.fingerprint !== after.fingerprint) {
        scope.undo = [...scope.undo.slice(-19), { label, before, after }];
        scope.redo = [];
        sync();
      }
    } catch (error) {
      if (!isCurrent() || error.name === 'AbortError') throw canceledOperation();
      clear();
      // Even a network failure leaves the response's freshness unverified.
      // Reject instead of letting a caller replace newer collaboration data.
      // Preserve the committed result separately for recovering a created ID.
      error.operationSaved = true;
      error.savedData = data;
      if (!error.conflict && error.status !== 409) error.message = '修改已保存，但未能验证最新内容；撤销记录已清除，请刷新地图。';
      optionsRef.current.onError?.(error.message);
      throw error;
    }
    return data;
  }, mapId), [mapId, enqueue, clear, sync]);
  const restore = useCallback((direction) => enqueue(async ({ scope, isCurrent, assertCurrent }) => {
    if (!optionsRef.current.canEdit) return false;
    const source = direction === 'undo' ? scope.undo : scope.redo;
    const entry = source.at(-1);
    if (!entry) return false;
    const target = direction === 'undo' ? entry.before : entry.after;
    const expected = direction === 'undo' ? entry.after : entry.before;
    try {
      const response = await api.restoreCheckpoint(mapId, { token: target.token, expectedFingerprint: expected.fingerprint });
      assertCurrent();
      optionsRef.current.onApply?.(response.map);
      source.pop();
      (direction === 'undo' ? scope.redo : scope.undo).push(entry);
      sync();
      return true;
    } catch (error) {
      if (!isCurrent()) return false;
      // A connection failure did not restore content. Keep the entry so the
      // user can retry; discard it only when the server rejects its validity.
      if (error.conflict || [401, 403, 404, 409].includes(error.status)) clear();
      if (error.latest) optionsRef.current.onApply?.(error.latest);
      optionsRef.current.onError?.(error.message);
      return false;
    }
  }, mapId).catch((error) => {
    if (error.name === 'AbortError') return false;
    throw error;
  }), [mapId, enqueue, clear, sync]);
  return { run, undo: () => restore('undo'), redo: () => restore('redo'), clear, busy, canUndo: undoEntries.length > 0 && refs.current.undo.length > 0, canRedo: redoEntries.length > 0 && refs.current.redo.length > 0 };
}
